package local.castle.tv;
/** Wait for changed publication followed by a quiet interval, with an explicit deadline. */
public final class SourceRefresh {public boolean active,changed;public long started,lastChange;long pausedAt=-1;String signature="";public void begin(long now,String value){started=lastChange=now;pausedAt=-1;signature=value;active=true;changed=false;}public void observe(long now,String value){if(active&&pausedAt<0&&!signature.equals(value)){signature=value;lastChange=now;changed=true;}}public boolean done(long now){return active&&pausedAt<0&&(now-started>=45000||changed&&now-started>=6000&&now-lastChange>=2500);}public void pause(long now){if(active&&pausedAt<0)pausedAt=now;}public void resume(long now){if(pausedAt>=0){long gap=Math.max(0,now-pausedAt);started+=gap;lastChange+=gap;pausedAt=-1;}}public void finish(){active=false;pausedAt=-1;}}
